{
  "items": [
    {
      "title": "Election and Social Data of the Districts and Municipalities of the German Reich from 1920 to 1933 (Wahl- und Sozialdaten der Kreise und Gemeinden des Deutschen Reiches von 1920 bis 1933)",
      "url_or_doi": "https://doi.org/10.4232/1.8013",
      "justification": "A highly relevant historical dataset from the GESIS Data Archive covering the German Reich between 1920 and 1933. Includes Reichstag election results, population statistics, religious affiliations, occupational structures, and unemployment data at district and municipal levels. Particularly useful for examining political changes, the rise of the Nazi Party, and relationships between socioeconomic conditions and voting behavior during the Weimar Republic."
    },
    {
      "title": "German Weimar Republic Data, 1919–1933",
      "url_or_doi": "https://www.icpsr.umich.edu/web/ICPSR/studies/42",
      "justification": "An extensive historical dataset provided by the Inter-university Consortium for Political and Social Research (ICPSR). Contains electoral and demographic information from 1919 to 1933, including Reichstag elections, presidential elections in 1925 and 1932, and national referendums. Also incorporates information from the 1925 German census, including religion, occupations, and urban populations. Suitable for historical research into political instability, electoral behavior, and the collapse of the Weimar Republic."
    },
    {
      "title": "Voters and Elections in the Weimar Republic, 1920–1933 (Wähler und Wahlen in der Weimarer Republik)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA8521",
      "justification": "A historical election dataset documenting voting patterns and political developments during the Weimar Republic. Includes Reichstag election results from 1920 to 1933, electoral district information, and statistical material on the social composition of voters. Particularly relevant for investigating the transformation of German politics during the 1920s and early 1930s, including the electoral rise of extremist political parties."
    },
    {
      "title": "Elections and Referendums in the Weimar Republic, 1919–1933 (Wahlen und Abstimmungen in der Weimarer Republik)",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/de/project/details/1DE30CBBDC0755808E1495F11AB63E10",
      "justification": "A historical statistical collection associated with research by Jürgen W. Falter and colleagues. Provides detailed results of elections and referendums during the Weimar Republic, including electoral district data and social characteristics. Contains downloadable historical statistical files covering elections through March 1933. Useful for quantitative historical analysis of political polarization, geographical voting differences, and the development of support for National Socialism."
    },
    {
      "title": "Representatives in the Reichstag in the Weimar Republic, 1919–1933",
      "url_or_doi": "https://doi.org/10.4232/1.8007",
      "justification": "A GESIS historical dataset documenting 1,794 members of the Weimar National Assembly and Reichstag between 1919 and 1933. Relevant for studying the political elite, parliamentary representation, party affiliation, and institutional history of the German Reich. Particularly useful for examining changes in parliamentary composition during the economic and political crises of the late 1920s and early 1930s."
    },
    {
      "title": "Historical Statistics of Germany: National Economic Aggregates of the German Reich, 1925–1936",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/project/details/003F80531CBB5478F38185A87B588052",
      "justification": "A historical economic dataset covering the German Reich during 1925–1936. Contains national economic aggregates suitable for examining Germany's economic development during the late Weimar Republic and the early years of Nazi rule. Particularly useful for investigating economic fluctuations, the Great Depression, and the transition to the economic policies of National Socialist Germany."
    },
    {
      "title": "Basic Population Statistics in Germany, 1871–1939 (Grunddaten zur Bevölkerungsstatistik in Deutschland von 1871 bis 1939)",
      "url_or_doi": "https://access.gesis.org/dbk/29488",
      "justification": "A historical demographic data collection covering the German Reich, its constituent states, and Prussian provinces between 1871 and 1939. Provides systematically organized statistics on population size and demographic change. Particularly relevant for studying population developments during the 1920s and 1930s, including demographic changes during the Weimar Republic and the Nazi period. The extended coverage also allows comparisons with earlier decades of German history."
    },
    {
      "title": "Albrecht Ritschl's Historical Economic Datasets on Twentieth-Century Germany",
      "url_or_doi": "https://www.marshall.econ.cam.ac.uk/onlineresources/statistics/statistics-historical",
      "justification": "A collection of historical German economic statistics available through the University of Cambridge's Marshall Library resources. Includes annual national accounts for 1925–1938, corrected quarterly employment statistics for 1925–1938, additional quarterly economic indicators, and monetary statistics covering 1924–1943. Especially valuable for examining the Great Depression, unemployment, economic recovery, and economic policy under the Nazi regime. The collection provides downloadable Excel datasets."
    },
    {
      "title": "Historical Statistics Database (histat): German Economic and Social History",
      "url_or_doi": "https://histat.safe-frankfurt.de/index.php/en/index",
      "justification": "A historical statistical database providing access to quantitative research datasets on German economic, political, demographic, and social history. Contains historical time series relevant to the German Reich, including datasets covering the Weimar Republic and Nazi Germany. Particularly useful for identifying additional specialized datasets concerning industrial production, labor markets, population trends, elections, and economic transformations during the 1920s and 1930s."
    },
    {
      "title": "Statistical Yearbooks of the German Reich, 1880–1941/1942 (Statistisches Jahrbuch für das Deutsche Reich)",
      "url_or_doi": "https://www.bib.uni-mannheim.de/en/teaching-and-research/research-data-center-fdz/data-hosted-by-the-fdz/",
      "justification": "A historical statistical source documenting economic, demographic, and social developments in the German Reich. The University of Mannheim provides information about historical statistical yearbooks and related research data. The yearbooks contain extensive statistics relevant to the 1920s and 1930s, including population, employment, industry, agriculture, public finances, and social conditions. Particularly valuable for reconstructing economic and social developments across the Weimar and Nazi periods. This is a collection-level landing page rather than a single downloadable dataset."
    },
    {
      "title": "Historical German Census and Population Data at Municipal Level",
      "url_or_doi": "https://www.bib.uni-mannheim.de/en/teaching-and-research/research-data-center-fdz/data-hosted-by-the-fdz/",
      "justification": "The University of Mannheim Research Data Center describes historical census and population resources covering municipalities in the German Reich and subsequent German states. These resources are relevant for investigating local population characteristics and demographic structures during the 1920s and 1930s. They can support research on urbanization, population distribution, and regional differences during the Weimar Republic and National Socialist period. Availability and coverage depend on the individual census collection."
    }
  ]
}
